  "distractors": [
    {
      "text": "The bridge would allow the doctor to commute to a larger hospital on the mainland, reducing the need for his local practice.",
      "why_wrong": "The text does not suggest the doctor would move or commute; instead, it states the bridge would make his role 'unnecessary to maintain locally,' implying the service could be replaced or eliminated, not relocated."
    },
    {
      "text": "The bridge would bring so many new residents that the doctor would be overwhelmed and unable to keep up with demand.",
      "why_wrong": "This contradicts the text, which implies the bridge would reduce the need for local services like the doctor’s, not increase demand. The concern is about redundancy, not overwork."
    },
    {
      "text": "The bridge would make it easier for the doctor to travel to medical conferences, improving his skills and reducing the need for local care.",
      "why_wrong": "The text never mentions professional development or improved skills as a reason for the doctor’s role becoming unnecessary. The focus is on the bridge reducing the need for local medical services, not enhancing them."
    }
  ]
}
